"use client";

import React from "react";
import { useState, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Sparkles,
  Loader2,
  ImagePlus,
  Gavel,
  DollarSign,
  Info,
  Check,
  ChevronRight,
  ChevronLeft,
  Package,
  Disc3,
  AlertCircle,
  CheckCircle2,
  ArrowRight,
  X,
  CreditCard,
  Music,
} from "lucide-react";
import { genres, conditions } from "@/lib/mock-data";
import { motion, AnimatePresence } from "motion/react";
import { DashboardBottomNav } from "@/components/dashboard-bottom-nav";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import type { VinylAnalysis } from "@/lib/types";
import { ProtectedAIFeature } from "@/components/protected-ai-feature";
import { CollectionSelector } from "@/components/dashboard/collection-selector";
import type { Vinyl } from "@/lib/db/schema";

type PricingType = "fixed" | "auction";
type RecordType = "sealed" | "used" | null;
type WizardStep = "source" | "type" | "images" | "review";
type SourceType = "new" | "collection";

interface AISuggestion {
  field: string;
  value: string | number;
  accepted: boolean;
}

export default function NewListingPage() {
  // Wizard state
  const [wizardStep, setWizardStep] = useState<WizardStep>("source");
  const [sourceType, setSourceType] = useState<SourceType>("new");
  const [selectedCollectionItem, setSelectedCollectionItem] = useState<Vinyl | null>(null);
  const [recordType, setRecordType] = useState<RecordType>(null);

  // AI analysis state
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<VinylAnalysis | null>(null);

  // Form state
  const [title, setTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [genre, setGenre] = useState("");
  const [year, setYear] = useState("");
  const [condition, setCondition] = useState("");
  const [sleeveCondition, setSleeveCondition] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [quantity, setQuantity] = useState("1");

  // Pricing type state
  const [pricingType, setPricingType] = useState<PricingType>("fixed");

  // Auction state
  const [startingBid, setStartingBid] = useState("");
  const [reservePrice, setReservePrice] = useState("");
  const [buyItNowPrice, setBuyItNowPrice] = useState("");
  const [auctionDuration, setAuctionDuration] = useState("7");
  const [enableBuyItNow, setEnableBuyItNow] = useState(false);
  const [enableReserve, setEnableReserve] = useState(false);

  // Image state
  const [frontCover, setFrontCover] = useState<string | null>(null);
  const [backCover, setBackCover] = useState<string | null>(null);
  const [vinylFront, setVinylFront] = useState<string | null>(null);
  const [vinylBack, setVinylBack] = useState<string | null>(null);

  // Track which AI suggestions have been accepted
  const [acceptedSuggestions, setAcceptedSuggestions] = useState<Set<string>>(new Set());

  // Stripe Connect status
  const [stripeConnectStatus, setStripeConnectStatus] = useState<{
    hasAccount: boolean;
    status: string | null;
    accountId: string | null;
    isSeller: boolean;
  } | null>(null);
  const [isCheckingStripe, setIsCheckingStripe] = useState(true);
  const router = useRouter();

  // Check Stripe Connect status on mount
  useEffect(() => {
    const checkStripe = async () => {
      try {
        const res = await fetch("/api/stripe/connect/check");
        if (res.ok) {
          const data = await res.json();
          setStripeConnectStatus(data);
        }
      } catch (error) {
        console.error("Error checking Stripe:", error);
      } finally {
        setIsCheckingStripe(false);
      }
    };
    checkStripe();
  }, []);

  // Prefill form when collection item is selected
  useEffect(() => {
    if (selectedCollectionItem) {
      setTitle(selectedCollectionItem.title);
      setArtist(selectedCollectionItem.artist);
      setGenre(selectedCollectionItem.genre);
      setYear(selectedCollectionItem.year?.toString() || "");
      setCondition(selectedCollectionItem.condition);
      setSleeveCondition(selectedCollectionItem.sleeveCondition || "");
      setDescription(selectedCollectionItem.description || "");
      
      const images = selectedCollectionItem.images ? JSON.parse(selectedCollectionItem.images) : [];
      if (images.length > 0) {
        const frontCoverImg = images.find((img: any) => img.type === "front_cover");
        const backCoverImg = images.find((img: any) => img.type === "back_cover");
        if (frontCoverImg) setFrontCover(frontCoverImg.url);
        if (backCoverImg) setBackCover(backCoverImg.url);
      }

      setRecordType(selectedCollectionItem.type === "new" ? "sealed" : "used");
      setWizardStep("review");
    }
  }, [selectedCollectionItem]);

  const showStripeBanner =
    stripeConnectStatus?.isSeller &&
    (!stripeConnectStatus.hasAccount || stripeConnectStatus.status !== "active");

  const handleImageUpload = (type: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Create object URL for preview
    const url = URL.createObjectURL(file);
    if (type === "frontCover") setFrontCover(url);
    if (type === "backCover") setBackCover(url);
    if (type === "vinylFront") setVinylFront(url);
    if (type === "vinylBack") setVinylBack(url);

    // TODO: Upload to blob storage and get permanent URL
  };

  const canProceedToAnalysis = () => {
    if (recordType === "sealed") {
      return frontCover && backCover;
    }
    return frontCover && backCover && vinylFront && vinylBack;
  };

  const handleAnalyzeWithAI = async () => {
    if (!canProceedToAnalysis()) return;

    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
      const imageUrls = [frontCover, backCover];
      if (recordType === "used") {
        imageUrls.push(vinylFront, vinylBack);
      }

      const response = await fetch("/api/analyze-vinyl", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageUrls: imageUrls.filter(Boolean),
          isSealed: recordType === "sealed",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to analyze images");
      }

      const analysis: VinylAnalysis = await response.json();
      setAiAnalysis(analysis);

      // Pre-fill form with AI suggestions
      setTitle(analysis.title);
      setArtist(analysis.artist);
      setGenre(analysis.genre);
      setYear(analysis.year);
      setCondition(analysis.condition.overall);
      setSleeveCondition(analysis.condition.sleeveCondition);
      setDescription(analysis.description);
      setPrice(analysis.priceEstimate.suggested.toString());

      // Mark all as accepted initially
      setAcceptedSuggestions(
        new Set(["title", "artist", "genre", "year", "condition", "sleeveCondition", "description", "price"]),
      );

      // Move to review step
      setWizardStep("review");
    } catch (error) {
      console.error("Analysis error:", error);
      setAnalysisError("Failed to analyze images. Please try again or continue with manual entry.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAcceptSuggestion = (field: string) => {
    setAcceptedSuggestions((prev) => new Set([...prev, field]));
  };

  const handleRejectSuggestion = (field: string) => {
    setAcceptedSuggestions((prev) => {
      const newSet = new Set(prev);
      newSet.delete(field);
      return newSet;
    });
  };

  const renderStepIndicator = () => (
    <div className="flex items-center justify-center gap-2 mb-6">
      {["source", "type", "images", "review"].map((step, index) => {
        const stepNames = { source: "Source", type: "Type", images: "Images", review: "Review" };
        const isActive = wizardStep === step;
        const isCompleted = ["source", "type", "images", "review"].indexOf(wizardStep) > index;

        return (
          <React.Fragment key={step}>
            <div className="flex flex-col items-center">
              <div
                className={cn(
                  "w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-colors",
                  isActive
                    ? "bg-primary text-primary-foreground"
                    : isCompleted
                      ? "bg-primary/20 text-primary"
                      : "bg-muted text-muted-foreground",
                )}
              >
                {isCompleted ? <Check className="h-4 w-4" /> : index + 1}
              </div>
              <span className="text-xs mt-1 text-muted-foreground hidden sm:block">{stepNames[step as WizardStep]}</span>
            </div>
            {index < 3 && (
              <div
                className={cn(
                  "w-8 h-0.5 transition-colors",
                  isCompleted ? "bg-primary" : "bg-muted",
                )}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );

  const renderSourceStep = () => (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      <Card className="border-0 shadow-sm">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="text-lg sm:text-xl">Choose Source</CardTitle>
          <CardDescription>Create a new listing or select from your collection</CardDescription>
        </CardHeader>
        <CardContent className="p-4 pt-0 sm:p-6 sm:pt-0 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Card
              className={cn(
                "cursor-pointer transition-all hover:shadow-md",
                sourceType === "new" ? "ring-2 ring-primary" : "",
              )}
              onClick={() => setSourceType("new")}
            >
              <CardContent className="p-6 text-center">
                <Package className="h-12 w-12 mx-auto mb-4 text-primary" />
                <h3 className="font-semibold mb-2">New Listing</h3>
                <p className="text-sm text-muted-foreground">
                  Create a brand new listing from scratch
                </p>
              </CardContent>
            </Card>
            <Card
              className={cn(
                "cursor-pointer transition-all hover:shadow-md",
                sourceType === "collection" ? "ring-2 ring-primary" : "",
              )}
              onClick={() => setSourceType("collection")}
            >
              <CardContent className="p-6 text-center">
                <Music className="h-12 w-12 mx-auto mb-4 text-primary" />
                <h3 className="font-semibold mb-2">From Collection</h3>
                <p className="text-sm text-muted-foreground">
                  List a record from your collection
                </p>
              </CardContent>
            </Card>
          </div>

          {sourceType === "collection" && (
            <div className="mt-6">
              <h3 className="font-medium mb-4">Select from Collection</h3>
              <CollectionSelector
                onSelect={(vinyl) => {
                  setSelectedCollectionItem(vinyl);
                }}
              />
            </div>
          )}

          <div className="flex justify-end gap-2 pt-4">
            <Button
              variant="outline"
              onClick={() => router.back()}
              className="rounded-full"
            >
              Cancel
            </Button>
            <Button
              onClick={() => {
                if (sourceType === "collection" && !selectedCollectionItem) {
                  alert("Please select a record from your collection");
                  return;
                }
                if (sourceType === "new") {
                  setWizardStep("type");
                } else {
                  // Collection item selected, skip to review
                  setWizardStep("review");
                }
              }}
              className="rounded-full"
              disabled={sourceType === "collection" && !selectedCollectionItem}
            >
              Continue
              <ChevronRight className="h-4 w-4 ml-2" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );

  const renderTypeStep = () => (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      <Card className="border-0 shadow-sm">
        <CardHeader className="text-center pb-2">
          <CardTitle className="text-xl sm:text-2xl">What are you selling?</CardTitle>
          <CardDescription>This helps us know which images to request</CardDescription>
        </CardHeader>
        <CardContent className="pt-6">
          <div className="grid sm:grid-cols-2 gap-4">
            <button
              onClick={() => setRecordType("sealed")}
              className={cn(
                "relative p-6 rounded-xl border-2 text-left transition-all hover:border-primary/50",
                recordType === "sealed" ? "border-primary bg-primary/5" : "border-border",
              )}
            >
              {recordType === "sealed" && (
                <div className="absolute top-3 right-3">
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                </div>
              )}
              <Package className="h-10 w-10 mb-4 text-primary" />
              <h3 className="font-semibold text-lg mb-1">New / Sealed</h3>
              <p className="text-sm text-muted-foreground">
                Factory sealed or brand new. We&apos;ll need front and back cover images.
              </p>
              <div className="mt-4 flex gap-2">
                <Badge variant="secondary" className="text-xs">
                  2 images required
                </Badge>
              </div>
            </button>

            <button
              onClick={() => setRecordType("used")}
              className={cn(
                "relative p-6 rounded-xl border-2 text-left transition-all hover:border-primary/50",
                recordType === "used" ? "border-primary bg-primary/5" : "border-border",
              )}
            >
              {recordType === "used" && (
                <div className="absolute top-3 right-3">
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                </div>
              )}
              <Disc3 className="h-10 w-10 mb-4 text-primary" />
              <h3 className="font-semibold text-lg mb-1">Used / Opened</h3>
              <p className="text-sm text-muted-foreground">
                Previously owned. We&apos;ll need cover images plus vinyl front and back.
              </p>
              <div className="mt-4 flex gap-2">
                <Badge variant="secondary" className="text-xs">
                  4 images required
                </Badge>
              </div>
            </button>
          </div>

          <div className="mt-6 flex justify-end">
            <Button onClick={() => setWizardStep("images")} disabled={!recordType} className="rounded-full">
              Continue
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );

  const renderImagesStep = () => (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      <Card className="border-0 shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg sm:text-xl">Upload Images</CardTitle>
          <CardDescription>
            {recordType === "sealed"
              ? "Upload front and back cover photos of your sealed vinyl"
              : "Upload photos of the cover (front & back) and the vinyl disc (both sides)"}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div>
            <h4 className="text-sm font-medium mb-3">Album Cover</h4>
            <div className="grid grid-cols-2 gap-4">
              {[
                { key: "frontCover", label: "Front Cover", value: frontCover, required: true },
                { key: "backCover", label: "Back Cover", value: backCover, required: true },
              ].map((item) => (
                <div key={item.key} className="space-y-2">
                  <Label className="text-xs text-muted-foreground flex items-center gap-1">
                    {item.label}
                    {item.required && <span className="text-red-500">*</span>}
                  </Label>
                  <div className="relative aspect-square rounded-xl border-2 border-dashed border-border overflow-hidden group cursor-pointer hover:border-primary transition-colors bg-muted/30">
                    {item.value ? (
                      <>
                        <img
                          src={item.value || "/placeholder.svg"}
                          alt={item.label}
                          className="w-full h-full object-cover"
                        />
                        <button
                          onClick={() => {
                            if (item.key === "frontCover") setFrontCover(null);
                            if (item.key === "backCover") setBackCover(null);
                          }}
                          className="absolute top-2 right-2 p-1 bg-black/50 rounded-full text-white hover:bg-black/70 transition-colors"
                        >
                          <X className="h-4 w-4" />
                        </button>
                      </>
                    ) : (
                      <div className="absolute inset-0 flex flex-col items-center justify-center text-muted-foreground">
                        <ImagePlus className="h-8 w-8 mb-2" />
                        <span className="text-xs">Click to upload</span>
                      </div>
                    )}
                    <input
                      type="file"
                      accept="image/*"
                      onChange={(e) => handleImageUpload(item.key, e)}
                      className="absolute inset-0 opacity-0 cursor-pointer"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {recordType === "used" && (
            <div>
              <h4 className="text-sm font-medium mb-3">Vinyl Disc</h4>
              <div className="grid grid-cols-2 gap-4">
                {[
                  { key: "vinylFront", label: "Vinyl Side A", value: vinylFront, required: true },
                  { key: "vinylBack", label: "Vinyl Side B", value: vinylBack, required: true },
                ].map((item) => (
                  <div key={item.key} className="space-y-2">
                    <Label className="text-xs text-muted-foreground flex items-center gap-1">
                      {item.label}
                      {item.required && <span className="text-red-500">*</span>}
                    </Label>
                    <div className="relative aspect-square rounded-xl border-2 border-dashed border-border overflow-hidden group cursor-pointer hover:border-primary transition-colors bg-muted/30">
                      {item.value ? (
                        <>
                          <img
                            src={item.value || "/placeholder.svg"}
                            alt={item.label}
                            className="w-full h-full object-cover"
                          />
                          <button
                            onClick={() => {
                              if (item.key === "vinylFront") setVinylFront(null);
                              if (item.key === "vinylBack") setVinylBack(null);
                            }}
                            className="absolute top-2 right-2 p-1 bg-black/50 rounded-full text-white hover:bg-black/70 transition-colors"
                          >
                            <X className="h-4 w-4" />
                          </button>
                        </>
                      ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-muted-foreground">
                          <Disc3 className="h-8 w-8 mb-2" />
                          <span className="text-xs">Click to upload</span>
                        </div>
                      )}
                      <input
                        type="file"
                        accept="image/*"
                        onChange={(e) => handleImageUpload(item.key, e)}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {analysisError && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-50 text-red-700 text-sm">
              <AlertCircle className="h-4 w-4 shrink-0" />
              {analysisError}
            </div>
          )}

          <div className="flex justify-between pt-4">
            <Button variant="outline" onClick={() => setWizardStep("type")} className="rounded-full">
              <ChevronLeft className="h-4 w-4 mr-1" />
              Back
            </Button>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setWizardStep("review")} className="rounded-full">
                Skip AI, Enter Manually
              </Button>
              <ProtectedAIFeature>
                <Button
                  onClick={handleAnalyzeWithAI}
                  disabled={!canProceedToAnalysis() || isAnalyzing}
                  className="rounded-full"
                >
                  {isAnalyzing ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Analyzing...
                    </>
                  ) : (
                    <>
                      <Sparkles className="h-4 w-4 mr-2" />
                      Analyze with AI
                    </>
                  )}
                </Button>
              </ProtectedAIFeature>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );

  const renderAISuggestionBadge = (field: string, suggestedValue: string | number) => {
    if (!aiAnalysis) return null;

    const isAccepted = acceptedSuggestions.has(field);

    return (
      <div className="flex items-center gap-1 mt-1">
        <Badge
          variant={isAccepted ? "default" : "secondary"}
          className={cn(
            "text-xs cursor-pointer transition-colors",
            isAccepted ? "bg-green-500 hover:bg-green-600" : "hover:bg-primary/20",
          )}
          onClick={() => (isAccepted ? handleRejectSuggestion(field) : handleAcceptSuggestion(field))}
        >
          <Sparkles className="h-3 w-3 mr-1" />
          AI: {suggestedValue}
          {isAccepted && <Check className="h-3 w-3 ml-1" />}
        </Badge>
      </div>
    );
  };

  const renderReviewStep = () => {
    const handleCreateListing = async () => {
      if (showStripeBanner) {
        alert("Please set up your Stripe Connect account first to receive payments.");
        return;
      }

      if (!title || !artist || !genre || !condition || !price) {
        alert("Please fill in all required fields");
        return;
      }

      try {
        const images: Array<{ type: string; url: string }> = [];
        if (frontCover) images.push({ type: "front_cover", url: frontCover });
        if (backCover) images.push({ type: "back_cover", url: backCover });
        if (vinylFront) images.push({ type: "vinyl_front", url: vinylFront });
        if (vinylBack) images.push({ type: "vinyl_back", url: vinylBack });

        const listingData = {
          title,
          artist,
          genre,
          year: year ? Number.parseInt(year) : null,
          condition,
          sleeveCondition: sleeveCondition || condition,
          vinylCondition: condition,
          type: recordType === "sealed" ? "new" : "used",
          description,
          price: Number.parseFloat(price),
          listingType: pricingType,
          startingBid: pricingType === "auction" ? Number.parseFloat(startingBid) : null,
          reservePrice: enableReserve ? Number.parseFloat(reservePrice) : null,
          buyNowPrice: enableBuyItNow ? Number.parseFloat(buyItNowPrice) : null,
          auctionEndDate:
            pricingType === "auction"
              ? new Date(Date.now() + Number.parseInt(auctionDuration) * 24 * 60 * 60 * 1000).toISOString()
              : null,
          quantity: Number.parseInt(quantity) || 1,
          images: images.length > 0 ? JSON.stringify(images) : null,
          isListed: true,
          isInCollection: true,
          aiSuggestedPrice: aiAnalysis?.priceEstimate.suggested || null,
          aiConditionNotes: aiAnalysis?.condition.notes || null,
        };

        // If converting from collection, update existing record
        if (selectedCollectionItem) {
          const res = await fetch(`/api/vinyls/${selectedCollectionItem.id}/list`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              price: Number.parseFloat(price),
              listingType: pricingType,
              startingBid: pricingType === "auction" ? Number.parseFloat(startingBid) : null,
              reservePrice: enableReserve ? Number.parseFloat(reservePrice) : null,
              buyNowPrice: enableBuyItNow ? Number.parseFloat(buyItNowPrice) : null,
              auctionEndDate:
                pricingType === "auction"
                  ? new Date(Date.now() + Number.parseInt(auctionDuration) * 24 * 60 * 60 * 1000).toISOString()
                  : null,
            }),
          });

          if (!res.ok) {
            const error = await res.json();
            if (error.requiresStripeConnect) {
              alert(error.error || "Please set up Stripe Connect to create listings");
              const checkRes = await fetch("/api/stripe/connect/check");
              if (checkRes.ok) {
                const data = await checkRes.json();
                setStripeConnectStatus(data);
              }
              return;
            }
            throw new Error(error.error || "Failed to create listing");
          }

          router.push("/dashboard/listings");
          return;
        }

        // Create new listing
        const res = await fetch("/api/vinyls", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(listingData),
        });

        if (!res.ok) {
          const error = await res.json();
          if (error.requiresStripeConnect) {
            alert(error.error || "Please set up Stripe Connect to create listings");
            const checkRes = await fetch("/api/stripe/connect/check");
            if (checkRes.ok) {
              const data = await checkRes.json();
              setStripeConnectStatus(data);
            }
            return;
          }
          throw new Error(error.error || "Failed to create listing");
        }

        const { vinyl } = await res.json();
        router.push("/dashboard/listings");
      } catch (error: any) {
        console.error("Error creating listing:", error);
        alert(error.message || "Failed to create listing. Please try again.");
      }
    };

    return (
      <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
        className="space-y-6"
      >
        <div className="grid lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <Card className="border-0 shadow-sm">
              <CardHeader className="pb-2">
                <CardTitle className="text-base sm:text-lg">Images</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex gap-2 overflow-x-auto pb-2">
                  {[frontCover, backCover, vinylFront, vinylBack]
                    .filter(Boolean)
                    .map((img, i) => (
                      <div key={i} className="relative shrink-0 w-20 h-20 rounded-lg overflow-hidden">
                        <img src={img! || "/placeholder.svg"} alt="" className="w-full h-full object-cover" />
                      </div>
                    ))}
                  <button
                    onClick={() => setWizardStep("images")}
                    className="shrink-0 w-20 h-20 rounded-lg border-2 border-dashed border-border flex items-center justify-center text-muted-foreground hover:border-primary hover:text-primary transition-colors"
                  >
                    <ImagePlus className="h-6 w-6" />
                  </button>
                </div>
              </CardContent>
            </Card>

            <Card className="border-0 shadow-sm">
              <CardHeader className="pb-2">
                <CardTitle className="text-base sm:text-lg">Album Details</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="title" className="text-sm">
                      Album Title *
                    </Label>
                    <Input
                      id="title"
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      placeholder="Kind of Blue"
                      className="h-10 rounded-lg"
                      required
                    />
                    {aiAnalysis && renderAISuggestionBadge("title", aiAnalysis.title)}
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="artist" className="text-sm">
                      Artist *
                    </Label>
                    <Input
                      id="artist"
                      value={artist}
                      onChange={(e) => setArtist(e.target.value)}
                      placeholder="Miles Davis"
                      className="h-10 rounded-lg"
                      required
                    />
                    {aiAnalysis && renderAISuggestionBadge("artist", aiAnalysis.artist)}
                  </div>
                  <div className="space-y-2">
                    <Label className="text-sm">Genre *</Label>
                    <Select value={genre} onValueChange={setGenre}>
                      <SelectTrigger className="h-10 rounded-lg">
                        <SelectValue placeholder="Select genre" />
                      </SelectTrigger>
                      <SelectContent>
                        {genres
                          .filter((g) => g !== "All Genres")
                          .map((g) => (
                            <SelectItem key={g} value={g}>
                              {g}
                            </SelectItem>
                          ))}
                      </SelectContent>
                    </Select>
                    {aiAnalysis && renderAISuggestionBadge("genre", aiAnalysis.genre)}
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="year" className="text-sm">
                      Year
                    </Label>
                    <Input
                      id="year"
                      value={year}
                      onChange={(e) => setYear(e.target.value)}
                      placeholder="1959"
                      className="h-10 rounded-lg"
                    />
                    {aiAnalysis && renderAISuggestionBadge("year", aiAnalysis.year)}
                  </div>
                </div>

                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label className="text-sm">Vinyl Condition *</Label>
                    <Select value={condition} onValueChange={setCondition}>
                      <SelectTrigger className="h-10 rounded-lg">
                        <SelectValue placeholder="Select condition" />
                      </SelectTrigger>
                      <SelectContent>
                        {conditions.map((c) => (
                          <SelectItem key={c} value={c} className="capitalize">
                            {c.replace("-", " ")}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {aiAnalysis &&
                      renderAISuggestionBadge("condition", aiAnalysis.condition.overall.replace("-", " "))}
                  </div>
                  <div className="space-y-2">
                    <Label className="text-sm">Sleeve Condition</Label>
                    <Select value={sleeveCondition} onValueChange={setSleeveCondition}>
                      <SelectTrigger className="h-10 rounded-lg">
                        <SelectValue placeholder="Select condition" />
                      </SelectTrigger>
                      <SelectContent>
                        {conditions.map((c) => (
                          <SelectItem key={c} value={c} className="capitalize">
                            {c.replace("-", " ")}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {aiAnalysis &&
                      renderAISuggestionBadge(
                        "sleeveCondition",
                        aiAnalysis.condition.sleeveCondition.replace("-", " "),
                      )}
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="description" className="text-sm">
                    Description
                  </Label>
                  <Textarea
                    id="description"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="Describe the condition, pressing details, and any notable features..."
                    rows={4}
                    className="rounded-lg resize-none"
                  />
                  {aiAnalysis && (
                    <div className="flex items-center gap-2 mt-1">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setDescription(aiAnalysis.description)}
                        className="text-xs h-7"
                      >
                        <Sparkles className="h-3 w-3 mr-1" />
                        Use AI description
                      </Button>
                      <span className="text-xs text-muted-foreground">AI description available</span>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>

            <Card className="border-0 shadow-sm">
              <CardHeader className="pb-2">
                <CardTitle className="text-base sm:text-lg">Pricing</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-3">
                  <div className="flex items-center gap-3">
                    <Button
                      variant={pricingType === "fixed" ? "default" : "outline"}
                      onClick={() => setPricingType("fixed")}
                      className="flex-1 rounded-full"
                    >
                      <DollarSign className="h-4 w-4 mr-2" />
                      Fixed Price
                    </Button>
                    <Button
                      variant={pricingType === "auction" ? "default" : "outline"}
                      onClick={() => setPricingType("auction")}
                      className="flex-1 rounded-full"
                    >
                      <Gavel className="h-4 w-4 mr-2" />
                      Auction
                    </Button>
                  </div>

                  {pricingType === "fixed" ? (
                    <div className="space-y-2">
                      <Label htmlFor="price" className="text-sm">
                        Price *
                      </Label>
                      <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                        <Input
                          id="price"
                          type="number"
                          step="0.01"
                          min="0"
                          value={price}
                          onChange={(e) => setPrice(e.target.value)}
                          className="pl-7 h-10 rounded-lg"
                          placeholder="0.00"
                          required
                        />
                      </div>
                      {aiAnalysis && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setPrice(aiAnalysis.priceEstimate.suggested.toString())}
                          className="text-xs h-7"
                        >
                          <Sparkles className="h-3 w-3 mr-1" />
                          Suggested: ${aiAnalysis.priceEstimate.suggested}
                        </Button>
                      )}
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <Label htmlFor="startingBid" className="text-sm">
                          Starting Bid *
                        </Label>
                        <div className="relative">
                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                          <Input
                            id="startingBid"
                            type="number"
                            step="0.01"
                            min="0"
                            value={startingBid}
                            onChange={(e) => setStartingBid(e.target.value)}
                            className="pl-7 h-10 rounded-lg"
                            placeholder="0.00"
                            required
                          />
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        <Switch
                          id="enableReserve"
                          checked={enableReserve}
                          onCheckedChange={setEnableReserve}
                        />
                        <Label htmlFor="enableReserve" className="text-sm">
                          Set Reserve Price
                        </Label>
                      </div>
                      {enableReserve && (
                        <div className="space-y-2">
                          <Label htmlFor="reservePrice" className="text-sm">
                            Reserve Price
                          </Label>
                          <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                            <Input
                              id="reservePrice"
                              type="number"
                              step="0.01"
                              min="0"
                              value={reservePrice}
                              onChange={(e) => setReservePrice(e.target.value)}
                              className="pl-7 h-10 rounded-lg"
                              placeholder="0.00"
                            />
                          </div>
                        </div>
                      )}

                      <div className="flex items-center gap-2">
                        <Switch
                          id="enableBuyItNow"
                          checked={enableBuyItNow}
                          onCheckedChange={setEnableBuyItNow}
                        />
                        <Label htmlFor="enableBuyItNow" className="text-sm">
                          Enable Buy It Now
                        </Label>
                      </div>
                      {enableBuyItNow && (
                        <div className="space-y-2">
                          <Label htmlFor="buyItNowPrice" className="text-sm">
                            Buy It Now Price
                          </Label>
                          <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                            <Input
                              id="buyItNowPrice"
                              type="number"
                              step="0.01"
                              min="0"
                              value={buyItNowPrice}
                              onChange={(e) => setBuyItNowPrice(e.target.value)}
                              className="pl-7 h-10 rounded-lg"
                              placeholder="0.00"
                            />
                          </div>
                        </div>
                      )}

                      <div className="space-y-2">
                        <Label htmlFor="auctionDuration" className="text-sm">
                          Auction Duration (days)
                        </Label>
                        <Select value={auctionDuration} onValueChange={setAuctionDuration}>
                          <SelectTrigger className="h-10 rounded-lg">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="3">3 days</SelectItem>
                            <SelectItem value="5">5 days</SelectItem>
                            <SelectItem value="7">7 days</SelectItem>
                            <SelectItem value="10">10 days</SelectItem>
                            <SelectItem value="14">14 days</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  )}

                  <div className="space-y-2">
                    <Label htmlFor="quantity" className="text-sm">
                      Quantity
                    </Label>
                    <Input
                      id="quantity"
                      type="number"
                      min="1"
                      value={quantity}
                      onChange={(e) => setQuantity(e.target.value)}
                      className="h-10 rounded-lg"
                      placeholder="1"
                    />
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {aiAnalysis && (
            <div className="lg:col-span-1">
              <Card className="border-0 shadow-sm sticky top-20 bg-gradient-to-br from-primary/5 to-accent/5">
                <CardHeader className="pb-2">
                  <CardTitle className="text-base flex items-center gap-2">
                    <Sparkles className="h-4 w-4 text-primary" />
                    AI Analysis
                  </CardTitle>
                  <CardDescription className="text-xs">{aiAnalysis.confidence}% confidence</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4 text-sm">
                  <div className="p-3 rounded-lg bg-background/80">
                    <p className="font-medium">{aiAnalysis.title}</p>
                    <p className="text-muted-foreground">
                      {aiAnalysis.artist} • {aiAnalysis.year}
                    </p>
                    {aiAnalysis.label && (
                      <p className="text-xs text-muted-foreground mt-1">{aiAnalysis.label}</p>
                    )}
                  </div>
                  <div className="p-3 rounded-lg bg-background/80">
                    <p className="text-xs bg-background/80 p-2 rounded-lg">{aiAnalysis.condition.notes}</p>
                  </div>
                  <div className="p-3 rounded-lg bg-background/80">
                    <div className="flex items-baseline gap-2">
                      <span className="text-2xl font-bold text-primary">${aiAnalysis.priceEstimate.suggested}</span>
                      <span className="text-xs text-muted-foreground">
                        (${aiAnalysis.priceEstimate.low} - ${aiAnalysis.priceEstimate.high})
                      </span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-2">{aiAnalysis.priceEstimate.reasoning}</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full rounded-full"
                    onClick={() => {
                      setTitle(aiAnalysis.title);
                      setArtist(aiAnalysis.artist);
                      setGenre(aiAnalysis.genre);
                      setYear(aiAnalysis.year);
                      setCondition(aiAnalysis.condition.overall);
                      setSleeveCondition(aiAnalysis.condition.sleeveCondition);
                      setDescription(aiAnalysis.description);
                      setPrice(aiAnalysis.priceEstimate.suggested.toString());
                    }}
                  >
                    <Check className="h-4 w-4 mr-2" />
                    Accept All Suggestions
                  </Button>
                </CardContent>
              </Card>
            </div>
          )}
        </div>

        <div className="flex justify-between pt-4">
          <Button variant="outline" onClick={() => setWizardStep("images")} className="rounded-full">
            <ChevronLeft className="h-4 w-4 mr-1" />
            Back
          </Button>
          <Button size="lg" className="rounded-full" onClick={handleCreateListing}>
            Create Listing
            <ArrowRight className="h-4 w-4 ml-2" />
          </Button>
        </div>
      </motion.div>
    );
  };

  return (
    <div className="min-h-screen pb-24 md:pb-8">
      <div className="p-4 md:p-6 space-y-6 max-w-7xl mx-auto">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold tracking-tight">Create Listing</h1>
          <p className="text-muted-foreground">Add a new vinyl record to the marketplace</p>
        </div>

        {showStripeBanner && (
          <Card className="border-amber-200 bg-amber-50/50">
            <CardContent className="p-4 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <CreditCard className="h-5 w-5 text-amber-600" />
                <div>
                  <p className="font-medium text-sm">
                    {!stripeConnectStatus?.hasAccount
                      ? "Set up payments to create listings"
                      : "Complete your payment setup"}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    You need an active Stripe Connect account to receive payments
                  </p>
                </div>
              </div>
              <Button
                size="sm"
                onClick={async () => {
                  try {
                    if (!stripeConnectStatus?.hasAccount) {
                      const accountRes = await fetch("/api/stripe/connect/create-account", {
                        method: "POST",
                      });
                      if (!accountRes.ok) throw new Error("Failed to create account");
                      const { accountId } = await accountRes.json();

                      const linkRes = await fetch("/api/stripe/connect/create-link", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ accountId }),
                      });
                      if (!linkRes.ok) throw new Error("Failed to create link");
                      const { url } = await linkRes.json();
                      window.location.href = url;
                    } else {
                      const linkRes = await fetch("/api/stripe/connect/create-link", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ accountId: stripeConnectStatus.accountId }),
                      });
                      if (!linkRes.ok) throw new Error("Failed to create link");
                      const { url } = await linkRes.json();
                      window.location.href = url;
                    }
                  } catch (error) {
                    alert("Failed to set up payments. Please try again.");
                  }
                }}
                className="rounded-full"
              >
                Set up payments
              </Button>
            </CardContent>
          </Card>
        )}

        {renderStepIndicator()}

        <AnimatePresence mode="wait">
          {wizardStep === "source" && renderSourceStep()}
          {wizardStep === "type" && renderTypeStep()}
          {wizardStep === "images" && renderImagesStep()}
          {wizardStep === "review" && renderReviewStep()}
        </AnimatePresence>
      </div>
      <DashboardBottomNav />
    </div>
  );
}
